<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../api';import type{Notification}from'../../types';const items=ref<Notification[]>([]);onShow(async()=>{items.value=await api.notifications()});async function read(item:Notification){if(!item.read){await api.readNotification(item.id);item.read=true}}</script>
<template><view class="page"><view v-for="item in items" :key="item.id" class="message card" :class="{'message--unread':!item.read}" @tap="read(item)"><view class="message__dot"/><view><text class="message__title">{{item.title}}</text><text class="message__content">{{item.content}}</text><text class="message__time">{{item.createdAt.slice(0,16).replace('T',' ')}}</text></view></view><view v-if="!items.length" class="empty">暂时没有新消息</view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.message{display:grid;grid-template-columns:20rpx 1fr;gap:18rpx;padding:28rpx;margin-bottom:20rpx}.message__dot{width:14rpx;height:14rpx;margin-top:12rpx;border-radius:50%;background:$line}.message--unread .message__dot{background:$primary}.message__title,.message__content,.message__time{display:block}.message__title{font-weight:900;font-size:30rpx}.message__content{color:$muted;line-height:1.6;margin:10rpx 0}.message__time{font-size:21rpx;color:$muted}.empty{text-align:center;color:$muted;padding-top:180rpx}</style>
